package swarm

func (r *InternalToolRegistry) registerConfigurationTools() {
	documentInput := map[string]any{"type": "object", "properties": map[string]any{"content": map[string]any{"type": "string", "description": "Inline YAML or JSON ConfigDocument"}, "format": map[string]any{"type": "string", "enum": []string{"yaml", "json"}}, "path": map[string]any{"type": "string", "description": "Path below the governed workspace config root"}, "operator_values": map[string]any{"type": "object", "description": "Optional operator-provided minimum brief values"}, "policy_values": map[string]any{"type": "object", "description": "Optional policy-enforced minimum brief values"}}}
	r.tools["preview_config_document"] = &InternalTool{Name: "preview_config_document", Description: "Validate and preview a supported ConfigDocument without saving or activating it.", InputSchema: documentInput, Handler: r.handlePreviewConfigDocument}
	r.tools["store_config_document"] = &InternalTool{Name: "store_config_document", Description: "Save an immutable, validated ConfigDocument revision without activating it.", InputSchema: documentInput, Handler: r.handleStoreConfigDocument}
	r.tools["activate_config_document"] = &InternalTool{Name: "activate_config_document", Description: "Activate or roll back to an explicit ConfigDocument revision after governance approval.", InputSchema: map[string]any{"type": "object", "properties": map[string]any{"record_id": map[string]any{"type": "string", "description": "Stored revision UUID"}, "action": map[string]any{"type": "string", "enum": []string{"activate", "rollback"}}}, "required": []string{"record_id"}}, Handler: r.handleActivateConfigDocument}
}
